mapper.update:
UPDATE trading_order SET limit_price = #{limitPrice}, lots = #{lots}, take_profit = #{takeProfit}, stop_loss = #{stopLoss},
  frozen_amount = #{frozenAmount}, notional_usd = #{notionalUsd}, revision = #{revision}
WHERE id = #{id} AND status = 'PENDING'

UPDATE trading_position SET lots = #{lots}, margin = #{margin}, fee = #{fee}, swap_total = #{swapTotal}, notional_usd = #{notionalUsd},
  liquidation_price = #{liquidationPrice}
WHERE id = #{id} AND status = 'OPEN'

mapper.select:
SELECT l.id, l.entry_type, l.amount, l.value_after, l.biz_type, l.biz_id, l.created_at
FROM trading_ledger l JOIN trading_account a ON a.id = l.account_id
WHERE a.user_id = #{userId} AND l.bucket = 'BALANCE' ORDER BY l.id DESC LIMIT #{limit}

where.if:
