mapper.sql:
WHERE status = 'OPEN'
AND symbol = #{symbol}
AND side = #{side}
AND (
  OR user_id IN #{u}
  OR public_no = #{no}
)

WHERE p.status = 'CLOSED'
AND p.symbol = #{symbol}
AND p.side = #{side}
AND (
  OR p.user_id IN #{u}
  OR p.public_no = #{no} OR pp.public_no = #{no}
)

FROM trading_ledger l JOIN trading_account a ON a.id = l.account_id
WHERE a.user_id = #{userId} AND l.bucket = 'BALANCE'
  AND l.entry_type IN #{t}
  AND l.created_at >= #{since}
